#include <iostream>
int g[3][2] = {{1, 2}, {0, 2}, {0, 1}};
bool vis[3];
bool dfs(int u, int par) {
    vis[u] = true;
    for (int v : g[u])
        if (v != par && (vis[v] || dfs(v, u))) return true;
    return false;
}
int main() { std::cout << (dfs(0, -1) ? "yes" : "no"); }

