#include <iostream>
int g[3][1] = {{1}, {2}, {0}};
bool vis[3], stk[3];
bool dfs(int u) {
    vis[u] = stk[u] = true;
    for (int v : g[u])
        if (stk[v] || (!vis[v] && dfs(v))) return true;
    return stk[u] = false;
}
int main() { std::cout << (dfs(0) ? "cycle" : "acyclic"); }

