#include <iostream>
int p[4];
int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
int main() {
    for (int i = 0; i < 4; i++) p[i] = i;
    int e[3][2] = {{0, 1}, {1, 2}, {0, 2}};
    for (auto& x : e) {
        int a = find(x[0]), b = find(x[1]);
        if (a == b) { std::cout << "cycle"; return 0; } else p[a] = b;
    }
    std::cout << "tree";
}

